import groovy.json.JsonOutput
import org.apache.nifi.processor.io.StreamCallback
import org.apache.nifi.components.state.Scope
import java.nio.charset.StandardCharsets

def flowFile = session.get()
if (!flowFile) return

// Получаем StateManager через context
def stateManager = context.getStateManager()

// 1. Генерация случайного 19-символьного ID
def ALPHABET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
def rnd = new Random()
def randomId = (1..19).collect { ALPHABET.charAt(rnd.nextInt(ALPHABET.length())) }.join()

// 2. Берём title из атрибута
def title = flowFile.getAttribute("lesson_title") ?: "Untitled"

// 3. Работа со state (сброс по таймауту 3 мин)
long now = System.currentTimeMillis()
def stateMap = stateManager.getState(Scope.CLUSTER).toMap()
long lastTime = (stateMap["last_order_time"] ?: "0").toLong()
int lastVal   = (stateMap["last_order_val"] ?: "0").toInteger()

int order = (now - lastTime > 30_000) ? 1 : (lastVal + 1)

// Обновляем состояние
stateManager.setState([
    "last_order_time": now.toString(),
    "last_order_val" : order.toString()
], Scope.CLUSTER)

// 4. Формируем итоговый JSON
def lessonJson = [
    lesson: [
        _id    : randomId,
        title  : title,
        order  : order,
        status : "published"
    ]
]

// 5. Записываем JSON в тело FlowFile
flowFile = session.write(flowFile, { input, output ->
    output.write(JsonOutput.toJson(lessonJson).getBytes(StandardCharsets.UTF_8))
} as StreamCallback)

// 6. Проставляем MIME и отправляем дальше
flowFile = session.putAttribute(flowFile, "mime.type", "application/json")
session.transfer(flowFile, REL_SUCCESS)
